PRAGMA foreign_keys=ON; CREATE TABLE customers(id INTEGER PRIMARY KEY,name TEXT,email TEXT UNIQUE); CREATE TABLE products(id INTEGER PRIMARY KEY,sku TEXT UNIQUE,name TEXT,category TEXT,price REAL CHECK(price>=0)); CREATE TABLE orders(id INTEGER PRIMARY KEY,order_no TEXT UNIQUE,customer_id INTEGER REFERENCES customers(id),customer_name TEXT,status TEXT,total REAL,order_date TEXT); CREATE TABLE order_items(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),product_id INTEGER REFERENCES products(id),qty INTEGER CHECK(qty>0),unit_price REAL CHECK(unit_price>=0)); CREATE TABLE suppliers(id INTEGER PRIMARY KEY,name TEXT,email TEXT,status TEXT);
